local ActivityMystery = Class("ActivityMystery")
local SwitchCellPath = "Game.Activity.ActivityMystery.Cell.ActivityMysterySwitchCell"
local ItemCell = "Game.Activity.ActivityMystery.Cell.ActivityMysteryItemCell"
local AniRoot = "Game.Activity.ActivityMystery.ActivityMysteryAniRoot"

local RewardType = {
    Limit = 1,
    Normal = 2,
}


local DrawType = {
    One = 1,
    Ten = 2,
}

function ActivityMystery:__init()
    self.switchEnv = {}
end

function ActivityMystery:__delete()
    self.controller = nil
end

function ActivityMystery:Awake()
    self:InitEnv()
    self:AddUIClick()
end

function ActivityMystery:InitEnv()
    CfUtils.SetActive(self.SwitchCell.gameObject,true)
    local env = CfUtils.GetLuaScr(self.SwitchCell,SwitchCellPath)
    if env then
        table.insert(self.switchEnv,env)
    end
end

function ActivityMystery:AddUIClick()
    SetButtonAction(self.BtnExplain,Bind(self,self.OnBtnExplainClick))
    SetButtonAction(self.BtnLeft,Bind(self,self.OnBtnLeftClick))
    SetButtonAction(self.BtnRight,Bind(self,self.OnBtnRightClick))
    SetButtonAction(self.BtnOne,Bind(self,self.OnBtnOneClick))
    SetButtonAction(self.BtnTen,Bind(self,self.OnBtnTenClick))
end

function ActivityMystery:Refresh(data)
    self.activityData = data
    self:RefreshBaseShow()
    GameUtils.Request(Interfaces.OverseaThemeBoxHome,{activityUuid = self.activityData.id},function(request, response)
        if checkNumber(response.errCode) == 0 then
            self.serverData = response.data
            self:RefreshUIShow()
        end
    end)
end

function ActivityMystery:RefreshBaseShow()
    ---@type ActivityUtils
    local ActivityUtils = import("Game.Activity.ActivityUtils")
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(self.activityData.startTime, self.activityData.endTime))
    local titleImgUrl = checkString(self.activityData.titleImage)
    if string.len(titleImgUrl) > 0 then
        CfUtils.FillWebRawImage(self.ImgTitleName, titleImgUrl)
    end
end

function ActivityMystery:RefreshUIShow()
    self:InitSwitchRootShow()
    self:RefreshCurrencyShow()
    self:RefreshTopGoodsShow()
end

function ActivityMystery:RefreshTopGoodsShow()
    ---@type ActivityUtils
    local ActivityUtils = import("Game.Activity.ActivityUtils")
    local consumeData = self:GetConsumeData()
    ActivityUtils.RefreshNavigatorGoods({consumeData.consume[1].goodsId})
end

function ActivityMystery:RefreshShow()
    self:RefreshRewardsShow()
    self:RefreshCurrencyShow()
    self:RefreshStockShow()
    self:RefreshBtnShow()
end

function ActivityMystery:RefreshStockShow()
    local data = self.poolData[self.selectIndex]
    if checkNumber(data.total) > 0 then
        local leaveNum = 0
        local bigNum = 0
        local bigTotal = 0
        local normalNum = 0
        local normalTotal = 0
        for i, v in pairs(data.rewards) do
            if v.stock > 0 then
                leaveNum = leaveNum + v.currentStock
                if v.rewardType == RewardType.Limit then
                    bigNum = bigNum + v.currentStock
                    bigTotal = bigTotal + v.stock
                elseif v.rewardType == RewardType.Normal then
                    normalNum = normalNum + v.currentStock
                    normalTotal = normalTotal + v.stock
                end
            end
        end
        CfUtils.FillText(self.TxtNum,string.format("<color=#ff41b7>%s</color>/%s", leaveNum, data.total))
        CfUtils.FillText(self.BigRewardNum,string.format("%s/%s", bigNum, bigTotal))
        CfUtils.FillText(self.NorRewardNum,string.format("%s/%s", normalNum, normalTotal))
        CfUtils.SetActive(self.TxtNum.gameObject, true)
        CfUtils.SetActive(self.BigRewardNum.gameObject, true)
        CfUtils.SetActive(self.NorRewardNum.gameObject, true)
    else
        CfUtils.SetActive(self.TxtNum.gameObject, false)
        CfUtils.SetActive(self.BigRewardNum.gameObject, false)
        CfUtils.SetActive(self.NorRewardNum.gameObject, false)
    end
end

function ActivityMystery:RefreshCurrencyShow()
    local isHaveStock = self:IsHaveStock(true)
    if isHaveStock then
        local consumeData = self:GetConsumeData()
        local consumeOne = consumeData.consume[1]
        CfUtils.FillCommonBtnConsumePopNode(self.BtnOneConsumePop, consumeOne.goodsId, consumeOne.num)
        local consumeTen = consumeData.tenConsume[1]
        CfUtils.FillCommonBtnConsumePopNode(self.BtnTenConsumePop, consumeTen.goodsId, consumeTen.num)
    end
end

function ActivityMystery:InitSwitchRootShow()
    self.totalCount = table.count(self.serverData.poolConf)
    
    local poolData = {}
    for i, v in pairs(self.serverData.poolConf) do
        table.insert(poolData,v)
    end
    table.sort(poolData,function(a, b)
        return a.id < b.id
    end)
    
    self.poolData = poolData
    
    for i = 1, self.totalCount do
        local env = self.switchEnv[i]
        if isNull(env) then
            local go = CfUtils.InstantiateGo(self.SwitchCell,self.SwitchRoot,false)
            if isNotNull(go) then
                CfUtils.SetActive(go.gameObject,true)
                env = CfUtils.GetLuaScr(go,SwitchCellPath)
                if env then
                    self.switchEnv[i] = env
                end
            end
        end
        env:InitData(i,Bind(self,self.OnSwitchClick))
        local selectIndex = self:GetClickIndex()
        env:RefreshShow(poolData[i], self.serverData.newFinishPoolId, selectIndex)
    end
end

function ActivityMystery:GetClickIndex()
    local index = 1
    for i, v in pairs(self.poolData) do
        local isUnLock = self.serverData.newFinishPoolId >= v.unlock
        if isUnLock then
            index = i
        end
    end
    return index > 0 and index or 1
end

function ActivityMystery:RefreshRewardsShow()
    local data = self.poolData[self.selectIndex]
    local limitRewards = {}
    local normalRewards = {}
    for i, v in pairs(data.rewards) do
        if v.rewardType == RewardType.Limit then
            table.insert(limitRewards,v)
        elseif v.rewardType == RewardType.Normal then
            table.insert(normalRewards,v)
        end
    end
    self:RefreshNodeReward(self.BigRewardNode, limitRewards)
    self:RefreshNodeReward(self.NorRewardNode, normalRewards)
end

function ActivityMystery:RefreshNodeReward(node, rewards)
    local childCount = node.transform.childCount
    if childCount >= table.count(rewards) then
        for i = 1, childCount do
            local go = node.transform:GetChild(i - 1)
            if go then
                if rewards[i] then
                    local env = CfUtils.GetLuaScr(go, ItemCell)
                    if isNotNull(env) then
                        env:RefreshShow(rewards[i])
                    end
                    CfUtils.SetActive(go.gameObject,true)
                else
                    CfUtils.SetActive(go.gameObject,false)
                end
            end
        end
    else
        for i, v in pairs(rewards) do
            local go
            if i > childCount then
                go = CfUtils.InstantiateGo(self.IconCell.gameObject,node.gameObject,false)
            else
                go = node.transform:GetChild(i - 1)
            end
            CfUtils.SetActive(go, true)
            local env = CfUtils.GetLuaScr(go,ItemCell)
            if isNotNull(env) then
                env:RefreshShow(v)
            end
        end
    end
end

