    local isMax = self.selectIndex == table.count(self.poolData)
    if not isMax then
        local index = self.selectIndex + 1
        self:OnSwitchClick(index)
        CfUtils.PlayAnimation(self.RewardIconNode,"ActivityMystery12002001_Reward_Refresh", true)
    end
    
    
