function ActivityMystery:OnBtnOneClick()
    self:StartDrawAni(DrawType.One)
end

function ActivityMystery:OnBtnTenClick()
    self:StartDrawAni(DrawType.Ten)
end

function ActivityMystery:OnSwitchClick(index)
    if isNotNull(self.selectIndex) and self.selectIndex == index then
        return
    end
    local lastIndex = self.selectIndex
    if isNotNull(lastIndex) then
       self.switchEnv[lastIndex]:SetLightState(false)
    end
    self.selectIndex = index
    self.switchEnv[self.selectIndex]:SetLightState(true)
    self:RefreshShow()
    self:RefreshBtnShow()
end

function ActivityMystery:RefreshBtnShow()
    local isPoolUnLock = self:IsPoolUnLock()
    if isPoolUnLock then
        CfUtils.SetUISwitchText(self.TxtEndTips,1)
        local isHaveStock = self:IsHaveStock(true)
        CfUtils.SetActive(self.BtnOne.gameObject,isHaveStock)
        CfUtils.SetActive(self.BtnTen.gameObject,isHaveStock)
        CfUtils.SetActive(self.TxtEndTips.gameObject,not isHaveStock)
    else
        CfUtils.SetActive(self.TxtEndTips.gameObject,true)
        CfUtils.SetUISwitchText(self.TxtEndTips,2)
        CfUtils.SetActive(self.BtnOne.gameObject,false)
        CfUtils.SetActive(self.BtnTen.gameObject,false)
    end
end
---click end--------------------

function ActivityMystery:IsPoolUnLock()
    return self.serverData.newFinishPoolId >= self.poolData[self.selectIndex].unlock
end

function ActivityMystery:StartDrawAni(drawType)
    local isPoolUnLock = self:IsPoolUnLock()
    if not isPoolUnLock then
        GameUtils.Toast(localize("当前卡池未解锁"))
        return
    end
    self.drawType = drawType
    local isEnough = self:IsItemEnough()
    if not isEnough then
        local consumeData = self:GetConsumeData()
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(consumeData.consume[1].goodsId)
        GameUtils.Toast(localize("_name_不足",{_name_ = goodsVo.name}))
        return
    end
    
    local isHaveStock = self:IsHaveStock()
    if not isHaveStock then
        GameUtils.Toast(localize("当前盲盒内剩余奖励数量不足"))
        return
    end
    
    local env = CfUtils.GetLuaScr(self.LeftItem,AniRoot)
    if isNotNull(env) then
        env:StartPlayAni(drawType, Bind(self,self.OnDraw))
    end
end

function ActivityMystery:IsHaveStock(ignoreType)
    local num = self.drawType == DrawType.One and 1 or 10
    local stock = self:GetCurrentStock()
    if ignoreType then
        return stock > 0
    end
    return stock >= num
end

function ActivityMystery:OnDraw(cb)
    local data = {activityUuid = self.activityData.id, poolId = self.poolData[self.selectIndex].id, type = self.drawType }
    GameUtils.Request(Interfaces.OverseaThemeBoxDraw, data,function(request,response)
        if checkNumber(response.errCode) == 0 then
            local responseData = response.data
            self.serverData.newFinishPoolId = responseData.newFinishPoolId
            self:UpdateGoodsStock(responseData.callRewardsIds)
            self:UpdateCost()
            self:RefreshShow()
            self:RefreshSwitchShow()
            local rewards = responseData.rewards
            if table.count(rewards) > 0 then
                GoodsUtils.DrawRewards(rewards, true)
                CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards, cb = cb } })
            end
        end
    end)
end

function ActivityMystery:UpdateCost()
    local consumeData = self:GetConsumeData()
    local data = self.drawType == DrawType.One and consumeData.consume[1] or consumeData.tenConsume[1]
    GoodsUtils.DrawRewards({{goodsId = data.goodsId, num = -data.num}}, true)
end

function ActivityMystery:UpdateGoodsStock(rewardsIds)
    local poolData = self.poolData[self.selectIndex]
    for i, v in pairs(poolData.rewards) do
        for k, j in pairs(rewardsIds) do
            if v.id == j and checkNumber(v.stock) > 0 and v.currentStock > 0 then
                v.currentStock = v.currentStock - 1
            end
        end
    end
end

function ActivityMystery:IsItemEnough()
    local consumeData = self:GetConsumeData()
    local data = self.drawType == DrawType.One and consumeData.consume[1] or consumeData.tenConsume[1]
    return GoodsUtils.GetThingNo(data.goodsId) >= checkNumber(data.num)
end

function ActivityMystery:RefreshSwitchShow()
    for i, v in pairs(self.switchEnv) do
        v:UpdateNowFinishId(self.serverData.newFinishPoolId)
        v:RefreshStateShow()
    end
end

function ActivityMystery:GetConsumeData()
    return self.serverData.scheduleConf
end

function ActivityMystery:GetCurrentStock()
    local rewards = self.poolData[self.selectIndex].rewards
    local totalStock = 0
    for i, v in pairs(rewards) do
        ---无限库存
        if v.stock == -1 then
            totalStock = 99999
        else
            if v.stock > 0 then
                totalStock = totalStock + v.currentStock
            end
        end
    end
    return totalStock
end

function ActivityMystery:OnDestroy()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
end

return ActivityMystery